class Solution:
    def furthestDistanceFromOrigin(self, moves: str) -> int:
        s = moves.count('L')
        t = moves.count('R')
        distance = 0
        for char in moves:
            if char == 'L':
                distance -= 1
            elif char == 'R':
                distance += 1
            else:
                if s > t:
                    distance -= 1
                elif t > s:
                    distance += 1
        return abs(distance)

